uint8_t stc_neopixel_supported(int16_t pin, uint8_t is800)
{
    return is800 && pin >= 0 && pin < 0x80 && digitalPinIsValid((uint8_t)pin);
}

uint8_t stc_neopixel_show(const uint8_t *pixels, uint16_t count, int16_t pin, uint8_t is800)
{
    uint8_t saved_ea;
    if (!pixels || !count || !stc_neopixel_supported(pin, is800)) return 0;
    saved_ea = IE & STC_IE_EA;
    IE &= (uint8_t)~STC_IE_EA;
    np_data = pixels;
    np_count = count;
    switch (pin) {

    case 0x00: np_p00(); break;

    case 0x01: np_p01(); break;

    case 0x02: np_p02(); break;

    case 0x03: np_p03(); break;

    case 0x04: np_p04(); break;

    case 0x05: np_p05(); break;

    case 0x06: np_p06(); break;

    case 0x07: np_p07(); break;

    case 0x10: np_p10(); break;

    case 0x11: np_p11(); break;

    case 0x12: np_p12(); break;

    case 0x13: np_p13(); break;

    case 0x14: np_p14(); break;

    case 0x15: np_p15(); break;

    case 0x16: np_p16(); break;

    case 0x17: np_p17(); break;

    case 0x20: np_p20(); break;

    case 0x21: np_p21(); break;

    case 0x22: np_p22(); break;

    case 0x23: np_p23(); break;

    case 0x24: np_p24(); break;

    case 0x25: np_p25(); break;

    case 0x26: np_p26(); break;

    case 0x27: np_p27(); break;

    case 0x30: np_p30(); break;

    case 0x31: np_p31(); break;

    case 0x32: np_p32(); break;

    case 0x33: np_p33(); break;

    case 0x34: np_p34(); break;

    case 0x35: np_p35(); break;

    case 0x36: np_p36(); break;

    case 0x37: np_p37(); break;

    case 0x40: np_p40(); break;

    case 0x41: np_p41(); break;

    case 0x42: np_p42(); break;

    case 0x43: np_p43(); break;

    case 0x44: np_p44(); break;

    case 0x45: np_p45(); break;

    case 0x46: np_p46(); break;

    case 0x47: np_p47(); break;

    case 0x50: np_p50(); break;

    case 0x51: np_p51(); break;

    case 0x52: np_p52(); break;

    case 0x53: np_p53(); break;

    case 0x54: np_p54(); break;

    case 0x55: np_p55(); break;

    case 0x56: np_p56(); break;

    case 0x57: np_p57(); break;

    case 0x60: np_p60(); break;

    case 0x61: np_p61(); break;

    case 0x62: np_p62(); break;

    case 0x63: np_p63(); break;

    case 0x64: np_p64(); break;

    case 0x65: np_p65(); break;

    case 0x66: np_p66(); break;

    case 0x67: np_p67(); break;

    case 0x70: np_p70(); break;

    case 0x71: np_p71(); break;

    case 0x72: np_p72(); break;

    case 0x73: np_p73(); break;

    case 0x74: np_p74(); break;

    case 0x75: np_p75(); break;

    case 0x76: np_p76(); break;

    case 0x77: np_p77(); break;

    }
    if (saved_ea) IE |= STC_IE_EA;
    return 1;
}
